def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    aggressive_count = 0
    desperate_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 90:
                    aggressive_count += 1

    if not alive_opps:
        return float(min(budget, 8.0))

    tight_supply = supply <= 18
    abundant_supply = supply >= 22

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency = 4
    elif hp <= 4:
        urgency = 3
    elif no_water_days >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if urgency >= 4:
        bid = max(95.0, highest_prev + 3.0)
    elif urgency == 3:
        if tight_supply:
            bid = max(82.0, avg_prev + 4.0)
        else:
            bid = max(72.0, avg_prev + 2.0)
    elif urgency == 2:
        if aggressive_count >= 2 and not tight_supply:
            bid = 48.0
        else:
            bid = max(58.0, avg_prev * 0.72)
    elif urgency == 1:
        if abundant_supply and aggressive_count >= 1:
            bid = 24.0
        elif tight_supply:
            bid = max(44.0, avg_prev * 0.55)
        else:
            bid = 34.0
    else:
        if abundant_supply:
            bid = 12.0
        elif tight_supply and desperate_count >= 2:
            bid = 36.0
        elif highest_prev >= 100:
            bid = 18.0
        else:
            bid = 26.0

    if day >= 8:
        bid += 8.0
    if day >= 9 and (hp <= 5 or no_water_days >= 1):
        bid += 12.0

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = 35.0
    elif hp > 2:
        reserve = 15.0

    max_affordable = max(0.0, budget - reserve)
    if max_affordable <= 0:
        return float(min(budget, 10.0))

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append(o)
        except Exception:
            continue

    # Baseline: conserve budget unless we're at risk
    if hp <= 2 or no_water_days >= 2:
        base_frac = 0.95
    elif hp <= 4 or no_water_days == 1:
        base_frac = 0.75
    else:
        base_frac = 0.55

    # Read yesterday bids from immediate trace to infer aggressive competitors
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    target_bid = None
    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))

        # If they were bidding near salary, we undercut slightly unless very safe
        if highest_prev >= 0.85 * DAILY_SALARY:
            if hp > 4:
                target_bid = 0.70 * DAILY_SALARY
            else:
                target_bid = 0.92 * DAILY_SALARY
        else:
            # Otherwise, bid around their average but slightly lower to win share cheaply
            target_bid = max(0.45 * DAILY_SALARY, avg_prev - 8.0)

    # Supply scaling: with higher supply, we can bid a bit less
    # Normalize supply to [0,1]
    denom = float(MAX_SUPPLY - MIN_SUPPLY)
    if denom <= 0:
        supply_norm = 0.5
    else:
        supply_norm = (supply - float(MIN_SUPPLY)) / denom
        if supply_norm < 0.0:
            supply_norm = 0.0
        if supply_norm > 1.0:
            supply_norm = 1.0

    supply_adjust = 1.0 - 0.15 * supply_norm  # bid slightly less when supply is high

    if target_bid is None:
        bid = base_frac * DAILY_SALARY * supply_adjust
    else:
        # Blend: ensure we respect our risk level
        risk_bid = base_frac * DAILY_SALARY * supply_adjust
        bid = 0.65 * risk_bid + 0.35 * float(target_bid)

    # Keep within budget and avoid bidding negative
    if budget <= 0:
        return 0.0

    if bid > budget:
        bid = budget
    if bid < 0.0:
        bid = 0.0

    # If supply is extremely low relative to WATER_REQ, ensure we bid enough to avoid starvation
    # (use integer thresholding carefully)
    # Approx water units available: supply / WATER_REQ
    water_units = supply / float(WATER_REQ)
    if water_units < 1.3:
        min_emergency = 0.85 * DAILY_SALARY
        if hp <= 3 and bid < min_emergency:
            bid = min_emergency
        if bid > budget:
            bid = budget

    return float(bid)

